            line.repeated("host-key", self.host_keys);
            line.string("name", self.name);
            line.bool("no-auth", self.no_auth);
            line.bool("peer", self.peer);
            line.bool("readonly", self.readonly);
            line.string("repository", self.repository);
            line.bool("step-up", self.step_up);
            line.bool("step-up-require-passkey", self.step_up_require_passkey);
            line.string("strip-prefix", self.strip_prefix);
            line.string("target", self.target);
            line.bool("team", self.team);
            line.arg(self.kind);
            let line = line.finish()?;
            self.c.t.call("integrations add", &line).await
