impl<'a> IntoFuture for Rename<'a> {
    type Output = Result<types::RenameResponse>;
    type IntoFuture = BoxFuture<'a, Self::Output>;

    fn into_future(self) -> Self::IntoFuture {
        Box::pin(async move {
            let new_name = self.new_name.clone();
            let mut line = Line::new("rename");
            line.arg(self.vm.name());
            line.arg(self.new_name);
            let line = line.finish()?;
            let value = self.vm.t.call("rename", &line).await?;
            let renamed = |key: &str, want: &str| value.get(key).and_then(Value::as_str) == Some(want);
            if !renamed("old_name", self.vm.name()) || !renamed("new_name", &new_name) {
                return Err(Error::protocol("rename"));
            }
            self.vm.renamed(&value)?;
            decode("rename", value)
        })
    }
}

