            self.wait_until.timeout(self.timeout)?;
            let mut line = Line::new("cp");
            line.bool("copy-tags", self.copy_tags);
            line.number("cpu", self.cpu);
            line.string("disk", self.disk);
            line.string("egress", self.egress.map(|p| p.as_str().to_string()));
            line.string("memory", self.memory);
            line.string("pool", self.pool);
            line.bool("standalone", self.standalone);
            line.arg(self.vm.name());
            line.opt_arg(self.name);
            let line = line.finish()?;
            if self.flush {
                self.vm.flush().await;
            }
            let info = self.vm.t.create("cp", line).await?;
