/// The `shelley` commands: see [`Vm::shelley`].
pub struct VmShelley<'a> {
    vm: &'a Vm,
}

impl<'a> VmShelley<'a> {
    /// Install or upgrade Shelley to the current version.
    ///
    /// CLI: `shelley install <vm>`
    ///
    /// Tag-scoped API keys may run this command.
    pub fn install(&self) -> ShelleyInstall<'a> {
        ShelleyInstall {
            vm: self.vm,
        }
    }
}

